const $=s=>document.querySelector(s), M=window.RosterModel;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let data,current,side='all',filter='all',roster={name:'Untitled roster',limit:500,army:null,warbands:[],unassigned:[],active:null,nextId:1},toastTimer;
const statLabels={movement:'Mv',fight:'Fv',shoot:'Sv',strength:'S',defence:'D',attack:'A',wounds:'W',courage:'C',intelligence:'I',might:'Might',will:'Will',fate:'Fate'};
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function save(){try{sessionStorage.setItem('palantir-roster-v2',JSON.stringify(roster))}catch{notify('This browser cannot retain the draft. Keep the tab open.');}}
function renderArmies(){const q=normalize($('#army-search').value);const visible=data.armies.filter(a=>(side==='all'||side===a.side)&&normalize(a.name).includes(q));$('#army-nav').innerHTML=['Good','Evil'].map(s=>{const group=visible.filter(a=>a.side===s);return group.length?`<div class="nav-label">FORCES OF ${s.toUpperCase()}</div>`+group.map(a=>`<a href="#${a.id}" data-army="${a.id}" class="${a.id===current.id?'active':''}" ${a.id===current.id?'aria-current="page"':''}><span>${esc(a.name)}${a.legacy?' <small>Legacy</small>':''}</span><span class="nav-count">${data.profiles.filter(p=>M.membership(p,a)).length}</span></a>`).join(''):''}).join('');const matches=q.length>=2?renderProfileMatches(q):'';$('#army-nav').innerHTML+=matches;if(!$('#army-nav').innerHTML)$('#army-nav').innerHTML=`<p class="no-armies">No matching armies${q.length>=2?' or profiles':''}.</p>`;document.querySelectorAll('[data-side]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.side===side)));}
function renderProfileMatches(q){const groups=new Map();for(const a of data.armies){if(side!=='all'&&a.side!==side)continue;for(const p of data.profiles){if(!normalize(p.name).includes(q))continue;const m=p.armies.find(x=>x.army===a.id);if(!m)continue;if(!groups.has(p.name))groups.set(p.name,[]);groups.get(p.name).push({army:a,profile:p,tier:m.tier});}}const names=[...groups.keys()].sort((x,y)=>normalize(x).startsWith(q)===normalize(y).startsWith(q)?x.localeCompare(y):normalize(x).startsWith(q)?-1:1);if(!names.length)return '';const limit=20;return `<div class="nav-label">PROFILES</div>`+names.slice(0,limit).map(n=>`<div class="profile-match"><div class="profile-match-name">${esc(n)}</div>${groups.get(n).map(e=>`<a href="#${e.army.id}/${e.profile.id}"><span>${esc(e.army.name)}${e.army.legacy?' <small>Legacy</small>':''}</span><small>${esc(e.tier||'')}</small></a>`).join('')}</div>`).join('')+(names.length>limit?`<p class="no-armies">${names.length-limit} more — refine your search.</p>`:'');}
function statCell(k,label,v,delta){return `<div${delta?` class="stat-changed" title="${delta>0?'+':''}${delta} from equipment"`:''}><abbr title="${esc(k)}">${label}</abbr><strong>${esc(v)}${['shoot','courage','intelligence'].includes(k)?'+':k==='movement'?'″':''}</strong></div>`;}
function stats(p,ids=[]){const e=M.effectiveStats(p,current,ids,data);const row=Object.entries(statLabels).filter(([k])=>e.stats[k]!==undefined).map(([k,label])=>statCell(k,label,e.stats[k],e.changed[k])).join('');const mount=e.mount?`<div class="mount-line"><span class="mount-name">${esc(e.mount.name)}</span>${Object.entries(statLabels).filter(([k])=>e.mount.stats[k]!==undefined).map(([k,label])=>statCell(k,label,e.mount.stats[k],0)).join('')}</div>`:'';return `<div class="stat-block"><div class="stats-grid">${row}</div>${mount}</div>`;}
function equipBlock(p,ids=[]){const r=M.equipmentRules(p,current,ids,data);return `<div class="equip-rules">${r.length?`<h4>Equipment rules</h4><dl>${r.map(x=>`<dt>${esc(x.name)}</dt><dd>${x.text.length>220?`<details class="long-rule"><summary>${esc(x.text.slice(0,x.text.lastIndexOf(' ',180)))}… <span>more</span></summary>${esc(x.text)}</details>`:esc(x.text)}</dd>`).join('')}</dl>`:''}</div>`;}
function defaultChoices(p){return M.missingChoices(p,current,[]).map(g=>g.slice().sort((x,y)=>x.points-y.points)[0].id);}
function optionsHTML(p){const required=M.requiredOptions(p,current),picked=defaultChoices(p),seen=new Set();return M.availableOptions(p,current).map(o=>{const mandatory=required.some(r=>r.name===o.name);const head=o.requireOne&&!seen.has(o.requireOne)?(seen.add(o.requireOne),'<p class="choose-one">Choose one (required):</p>'):'';return `${head}<label class="equipment-option${o.requireOne?' in-required-group':''}"><input type="checkbox" data-option="${o.id}" data-group="${esc(o.chooseOneKey||'')}" ${o.requireOne?`data-require="${esc(o.requireOne)}"`:''} ${mandatory?'checked disabled':picked.includes(o.id)?'checked':''}><span>${esc(o.name)}</span><b>+${o.points} pts${mandatory?' · required':''}</b></label>`}).join('');}
function profilePortrait(p){if(!p.portrait)return '';const c=p.portraitCrop;if(!c)return `<img class="unit-thumbnail" src="${esc(p.portrait)}" alt="" width="64" height="64" loading="lazy" decoding="async">`;return `<span class="profile-portrait" aria-hidden="true"><img src="${esc(p.portrait)}" alt="" loading="lazy" style="width:${c.sourceWidth/c.width*100}%;height:${c.sourceHeight/c.height*100}%;left:${-c.x/c.width*100}%;top:${-c.y/c.height*100}%"></span>`;}
function profilePhoto(p){if(!p.photo)return '';const c=p.photoCrop;const picture=c?`<span class="miniature-photo-crop"><img src="${esc(p.photo)}" alt="${esc(p.photoAlt||p.name+' miniature')}" loading="lazy" style="width:${c.sourceWidth/c.width*100}%;height:${c.sourceHeight/c.height*100}%;left:${-c.x/c.width*100}%;top:${-c.y/c.height*100}%"></span>`:`<img src="${esc(p.photo)}" alt="${esc(p.photoAlt||'Painted '+p.name+' miniature')}" width="${p.photoWidth||650}" height="${p.photoHeight||650}" loading="lazy">`;return `<figure class="miniature-photo">${picture}${p.photoVariant?`<figcaption>${esc(p.photoVariant)}</figcaption>`:''}${p.photoSource?`<a class="image-credit" href="${esc(p.photoSource)}" target="_blank" rel="noopener">${esc(p.photoCredit||'Image source')} ↗</a>`:p.photoCredit?`<span class="image-credit">${esc(p.photoCredit)}</span>`:''}</figure>`;}
const TIERS=[['Hero of Legend','Heroes of Legend'],['Hero of Valour','Heroes of Valour'],['Hero of Fortitude','Heroes of Fortitude'],['Minor Hero','Minor Heroes'],['Independent Hero','Independent Heroes']];
function tierRank(p,a){if(p.role!=='Hero')return p.tags.includes('Hero')?TIERS.length:TIERS.length+1;const t=(M.membership(p,a)?.tier||'').replace(/ - .*/,'');const i=TIERS.findIndex(x=>x[0]===t);return i<0?TIERS.length-1:i;}
function tierLabel(r){return r<TIERS.length?TIERS[r][1]:r===TIERS.length?'Heroes joining a warband':'Warriors';}
function renderProfiles(){const q=normalize($('#profile-search').value);const units=data.profiles.filter(p=>M.membership(p,current)&&(filter==='all'||p.role===filter)&&normalize(p.name+' '+p.tags.join(' ')).includes(q));units.sort((x,y)=>tierRank(x,current)-tierRank(y,current)||y.points-x.points||x.name.localeCompare(y.name));let lastTier=-1;$('#unit-count').textContent=units.length;$('#unit-list').innerHTML=units.map(p=>{const config=M.configuration(p,current,defaultChoices(p));const joins=p.role==='Warrior'&&p.tags.includes('Hero');const indepHero=joins&&data.profiles.some(q=>q.name===p.name&&q.role==='Hero'&&M.membership(q,current)?.tier==='Independent Hero');const tier=joins?(indepHero?'Independent Hero':'Hero')+' · joins a warband':M.membership(p,current).tier||p.role;const r=tierRank(p,current),head=r!==lastTier?`<h3 class="tier-heading">${tierLabel(r)}</h3>`:'';lastTier=r;return `${head}<article class="profile-card" id="${p.id}" data-profile="${p.id}"><div class="profile-header">${profilePortrait(p)}<div class="profile-name"><span class="profile-role">${esc(tier)}${p.legacy?' · Legacy':''}</span><h3>${esc(p.name)}</h3><span class="profile-tags">${esc(p.tags.join(' · '))}</span></div><div class="profile-price"><strong data-price>${config.points}</strong><small>POINTS</small></div></div>${stats(p,defaultChoices(p))}<details class="profile-details"><summary>Equipment & profile details <span>+</span></summary><div class="details-content">${profilePhoto(p)}<div><h4>Included equipment</h4><p>${esc(p.wargear.join(', ')||'See official profile.')}</p>${p.actions.length?`<h4>Heroic actions</h4><p>${ruleLinks(p.actions)}</p>`:''}${p.rules.length?`<h4>Special rule index</h4><p>${ruleLinks(p.rules)}</p>`:''}${p.base.length?`<h4>Base size</h4><p>${esc(p.base.join(' / '))}</p>`:''}${equipBlock(p,defaultChoices(p))}<h4>Equipment options</h4>${optionsHTML(p)||'<p>No priced options in this dataset.</p>'}<p class="subtle">The characteristics above include the selected equipment (changed values are underlined). Apply army-specific rules during play.</p></div></div></details><div class="profile-footer"><span>${esc(p.role)} profile</span><button class="add-button" data-add="${p.id}">${p.role==='Hero'?'+ Create warband':'+ Add to warband'}</button></div></article>`}).join('')||'<div class="empty">No matching profiles. Try another name or profile type.</div>';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));updateAddButtons();}
function armyRulesHTML(a,open){const add=a.additionalRules||[],sp=a.armyRules||[];return `${add.length?`<h4>Additional rules</h4><ul class="army-additional">${add.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:''}${sp.length?`<h4>Special rules</h4><dl class="army-special">${sp.map(r=>`<dt>${esc(r.name)}</dt><dd>${esc(r.text)}</dd>`).join('')}</dl>`:''}`;}
function renderArmyRules(){const a=current,box=$('#army-rules'),n=(a.additionalRules||[]).length+(a.armyRules||[]).length;box.hidden=!n;if(!n)return;const pl=(n,w)=>n+' '+w+(n===1?'':'s'),sp=(a.armyRules||[]).length,ad=(a.additionalRules||[]).length;box.open=false;$('#army-rules-count').textContent=[sp?pl(sp,'special rule'):'',ad?pl(ad,'additional rule'):''].filter(Boolean).join(' · ');$('#army-rules-body').innerHTML=armyRulesHTML(a);}
// Rule text for a name; "Leader (Khazad Guard)" falls back to another "Leader (…)" entry, whose wording is generic.
let ruleIndex=null;
function ruleText(name){const R=data.rules||{},G=data.gear||{};if(!ruleIndex){ruleIndex={};for(const k in R)ruleIndex[k.toLowerCase()]=R[k];}const n=name.trim().toLowerCase(),base=n.replace(/\s*\(.*\)\s*$/,'');const hit=R[name]||ruleIndex[n]||ruleIndex[base]||G[n]?.text||G[base]?.text;if(hit)return hit;const sib=Object.keys(ruleIndex).find(k=>k!==n&&k.startsWith(base+' ('));return sib?ruleIndex[sib]:'';}
function ruleLinks(names){return names.map(n=>ruleText(n)?`<button type="button" class="rule-term" data-rule="${esc(n)}">${esc(n)}</button>`:`<span class="rule-term plain">${esc(n)}</span>`).join('<span class="rule-sep"> · </span>');}
function selectArmy(id){const a=data.armies.find(a=>a.id===id);if(!a)return;current=a;filter='all';$('#profile-search').value='';$('#army-title').textContent=a.name;$('#crumb').textContent=a.name;$('#side-label').textContent='Forces of '+a.side;$('#eyebrow').textContent='FORCES OF '+a.side.toUpperCase();$('#army-legacy').hidden=!a.legacy;$('#profile-count').textContent=data.profiles.filter(p=>M.membership(p,a)).length+' available profiles';document.title=location.hash.slice(1)?a.name+' — MESBG Army Book':'MESBG Army Book — Unofficial Armies, Profiles & Warband Builder';renderArmyRules();renderArmies();renderProfiles();renderRoster();closeMenu();}
function closeMenu(){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
function rosterArmy(){return data.armies.find(a=>a.id===roster.army);}
function heroName(w){return data.profiles.find(p=>p.id===w.hero.profile).name;}
function wbOptions(exclude){const a=rosterArmy();return roster.warbands.filter(w=>w.id!==exclude&&!(a&&M.independent(w,a,data))).map(w=>`<option value="${w.id}">Warband ${roster.warbands.indexOf(w)+1} · ${esc(heroName(w))}</option>`).join('');}
function updateAddButtons(){document.querySelectorAll('[data-add]').forEach(b=>{const p=data.profiles.find(p=>p.id===b.dataset.add);b.disabled=false;b.textContent=p.role==='Hero'?'+ Create warband':'+ Add to warband';});}
function rowHTML(e,source){const p=data.profiles.find(p=>p.id===e.profile),c=M.configuration(p,rosterArmy(),e.options);return `<div class="roster-entry" data-source="${source}" data-key="${esc(e.key)}"><div class="roster-entry-top"><a href="#${roster.army}/${p.id}">${esc(p.name)}</a><strong>${c.points*e.quantity}<small> pts</small></strong></div><p>${esc(c.options.map(o=>o.name).join(', ')||'Base equipment')}</p><div class="quantity-controls"><button data-step="-1" aria-label="Remove one ${esc(p.name)}">−</button><span>${e.quantity}</span><button data-step="1" ${p.unique?'disabled':''} aria-label="Add one ${esc(p.name)}">+</button><button class="move-entry" data-move ${roster.warbands.filter(w=>w.id!==source).length?'':'disabled'}>Move</button><button class="remove-entry" data-remove>Remove</button></div></div>`;}
function renderRequired(){const box=$('#army-required'),names=current?.required||[];box.hidden=!names.length;if(!names.length){box.innerHTML='';return;}const inRoster=n=>roster.army===current.id&&M.allEntries(roster).some(e=>data.profiles.find(p=>p.id===e.profile)?.name===n);const hero=n=>data.profiles.find(p=>p.name===n&&p.role==='Hero'&&M.membership(p,current))||data.profiles.find(p=>p.name===n&&M.membership(p,current));box.innerHTML=`<strong>${names.length>1?'Required heroes':'Required hero'}</strong><p>A ${esc(current.name)} army must include ${names.length>1?'all of these heroes':'this hero'}.</p><ul>${names.map(n=>{const p=hero(n);return `<li><a href="#${current.id}/${p.id}">${esc(n)}</a>${inRoster(n)?'<span class="required-ok">✓ In your roster</span>':`<button data-required-add="${p.id}">+ Add</button>`}</li>`}).join('')}</ul>`;}
function renderRoster(){const a=rosterArmy(),total=M.total(roster,data.profiles,data.armies),all=M.allEntries(roster),qty=all.reduce((s,e)=>s+e.quantity,0);$('#points-total').textContent=total;$('#points-total').classList.toggle('over',total>roster.limit);$('#header-count').textContent=qty;$('#roster-count').textContent=roster.warbands.length+' warbands · '+qty+' selections';$('#remaining').textContent=total>roster.limit?(total-roster.limit)+' over limit':(roster.limit-total)+' remaining';$('#points-bar').style.width=Math.min(100,total/roster.limit*100)+'%';$('#points-bar').classList.toggle('over',total>roster.limit);$('#roster-army').textContent=a?.name||'No army selected yet';$('#roster-army').classList.toggle('empty',!a);$('#clear-roster').disabled=!qty;$('#print-roster').disabled=!qty;
const openIds=new Set([...document.querySelectorAll('.warband-group[open]')].map(d=>d.dataset.id));const priorIds=new Set([...document.querySelectorAll('.warband-group')].map(d=>d.dataset.id));
$('#roster-entries').innerHTML=roster.warbands.map((w,i)=>{const p=data.profiles.find(p=>p.id===w.hero.profile),c=M.configuration(p,a,w.hero.options),n=M.warriorCount(w,data),cap=M.capacity(w,a,data),pts=[w.hero,...w.entries].reduce((v,e)=>v+M.configuration(data.profiles.find(p=>p.id===e.profile),a,e.options).points*e.quantity,0);return `<details class="warband-group " data-id="${w.id}" ${openIds.has(w.id)||!priorIds.has(w.id)?'open':''}><summary><span class="warband-label">WARBAND ${i+1}</span><div class="warband-name"><strong>${esc(p.name)}</strong><span>${pts} pts</span></div><div class="warband-capacity ${cap!==null&&n>cap?'over':''}">${M.independent(w,a,data)?'Independent Hero · no followers':n+' / '+(cap??'?')+' warriors · base capacity'}</div></summary><div class="warband-hero"><a href="#${a.id}/${p.id}">Hero · ${c.points} pts</a><p>${esc(c.options.map(o=>o.name).join(', ')||'Base equipment')}</p><button data-delete-warband="${w.id}">Remove hero…</button></div>${w.entries.map(e=>rowHTML(e,w.id)).join('')||(M.independent(w,a,data)?'':'<div class="warband-empty">No warriors yet</div>')}</details>`}).join('')+(roster.unassigned.length?`<div class="unassigned-group"><strong>Assign existing warriors</strong><p>Choose Move to place these previous roster entries into a warband.</p>${roster.unassigned.map(e=>rowHTML(e,'unassigned')).join('')}</div>`:'')||'<p class="roster-empty">Your roster starts with a hero.<br><span>Select <strong>+ Create warband</strong> on a hero profile, then add warriors to their group.</span></p>';
const missing=a?.required.filter(name=>!all.some(e=>data.profiles.find(p=>p.id===e.profile)?.name===name))||[];const indep=roster.warbands.filter(w=>M.independent(w,a,data)&&M.warriorCount(w,data)>0);const over=roster.warbands.filter(w=>{const cap=M.capacity(w,a,data);return cap!==null&&M.warriorCount(w,data)>cap&&!indep.includes(w)});const noChoice=a?[...new Set(all.filter(e=>{const p=data.profiles.find(p=>p.id===e.profile);return p&&M.missingChoices(p,a,e.options).length}).map(e=>data.profiles.find(p=>p.id===e.profile).name))]:[];$('#roster-warnings').textContent=[noChoice.length?'Missing required equipment choice: '+noChoice.join(', ')+'.':'',missing.length?'Required hero: '+missing.join(', '):'',indep.length?'Independent Heroes may never have Followers — move the warriors led by '+indep.map(heroName).join(', ')+' to another warband.':'',over.length?'Above base capacity: '+over.map(heroName).join(', ')+'.':'',roster.unassigned.length?'Some warriors still need a warband.':'',qty?'Capacities use heroic tiers. Check army-specific capacity changes and warrior eligibility before play.':''].filter(Boolean).join(' ');updateAddButtons();renderRequired();}
function selectedOptions(card){return [...card.querySelectorAll('[data-option]:checked')].map(e=>e.dataset.option);}
function addProfile(id,options,targetId=null){const p=data.profiles.find(p=>p.id===id);if(!p)throw Error('Unknown profile.');M.addEntry(roster,p,current,options,targetId,1,data);save();renderRoster();return {profile:p.name,points:M.total(roster,data.profiles,data.armies)};}
function route(){const [army,profile]=location.hash.slice(1).split('/');if(data.armies.some(a=>a.id===army)){selectArmy(army);if(profile){const card=document.getElementById(profile);if(card){card.querySelector('details').open=true;requestAnimationFrame(()=>card.scrollIntoView({block:'start'}));}}else window.scrollTo({top:0,behavior:'instant'});}}
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw Error('Profile data could not be loaded.');data=M.withoutLegacy(await response.json());try{const draft=JSON.parse(sessionStorage.getItem('palantir-roster-v2')||sessionStorage.getItem('palantir-roster-v1')||'null');if(draft){roster=M.prune(M.migrate(draft,data),data);M.total(roster,data.profiles,data.armies);}}catch{roster=M.migrate(null,data);}save();$('#points-limit').value=roster.limit;$('#data-count').textContent=data.armies.length+' armies · '+data.profiles.length+' profiles';$('#data-version').textContent=data.version;$('#repository').hidden=false;selectArmy(data.armies.some(a=>a.id===location.hash.slice(1).split('/')[0])?location.hash.slice(1).split('/')[0]:'riders-of-theoden');route();renderRoster();}catch(e){$('#load-error').hidden=false;$('#load-error').textContent='The profile repository could not load. Please reload to try again.';$('#army-nav').textContent='Repository unavailable.';console.error(e);}}
$('#army-search').addEventListener('input',()=>data&&renderArmies());$('#profile-search').addEventListener('input',()=>data&&renderProfiles());document.querySelectorAll('[data-side]').forEach(b=>b.addEventListener('click',()=>{side=b.dataset.side;if(data)renderArmies()}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;if(data)renderProfiles()}));
let pendingProfile=null;
$('#army-required').addEventListener('click',e=>{const b=e.target.closest('[data-required-add]');if(!b)return;try{const result=addProfile(b.dataset.requiredAdd,defaultChoices(data.profiles.find(p=>p.id===b.dataset.requiredAdd)));notify(result.profile+' created a warband.');}catch(err){notify(err.message);}});
$('#unit-list').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(!b)return;const p=data.profiles.find(p=>p.id===b.dataset.add),options=selectedOptions(b.closest('.profile-card'));if(p.role==='Hero'){try{const result=addProfile(p.id,options);notify(result.profile+' created a warband.');}catch(err){notify(err.message);}return;}
if(roster.army&&roster.army!==current.id){notify('Your roster uses another army. Clear it before starting a different army.');return;}
pendingProfile={id:p.id,options,army:current.id};$('#add-profile-name').textContent=p.name;$('#add-warband-error').textContent='';$('#warband-choices').innerHTML=roster.warbands.length?roster.warbands.map((w,i)=>{const cap=M.capacity(w,current,data),count=M.warriorCount(w,data);if(M.independent(w,current,data))return `<button class="warband-choice" disabled><span>Warband ${i+1} · ${esc(heroName(w))}</span><small>Independent Hero · cannot lead warriors</small></button>`;return `<button class="warband-choice" data-add-target="${w.id}"><span>Warband ${i+1} · ${esc(heroName(w))}</span><small>${count} / ${cap??'?'} warriors · ${cap!==null&&count>=cap?'at base capacity':'base capacity'}</small></button>`}).join(''):'<p>Add a hero to lead your first warband.</p><button class="warband-choice" id="browse-heroes">Browse hero profiles</button>';$('#add-warband-dialog').showModal();});
$('#cancel-add-warband').addEventListener('click',()=>$('#add-warband-dialog').close());
$('#warband-choices').addEventListener('click',e=>{if(e.target.closest('#browse-heroes')){filter='Hero';$('#profile-search').value='';renderProfiles();$('#add-warband-dialog').close();return;}const b=e.target.closest('[data-add-target]');if(!b||!pendingProfile)return;try{if(current.id!==pendingProfile.army)throw Error('The selected army changed. Reopen the profile to add it.');const w=roster.warbands.find(w=>w.id===b.dataset.addTarget);if(!w)throw Error('This warband no longer exists.');const destination=heroName(w),result=addProfile(pendingProfile.id,pendingProfile.options,w.id);$('#add-warband-dialog').close();pendingProfile=null;notify(result.profile+' added to '+destination+'.');}catch(err){$('#add-warband-error').textContent=err.message;}});
$('#unit-list').addEventListener('change',e=>{if(!e.target.matches('[data-option]'))return;const input=e.target,card=input.closest('.profile-card');if(!input.checked&&input.dataset.require&&![...card.querySelectorAll(`[data-require="${input.dataset.require}"]`)].some(x=>x.checked)){input.checked=true;notify('This profile must take one of these options.');return;}if(input.checked&&input.dataset.group){for(const other of card.querySelectorAll('[data-option]')){if(other!==input&&other.dataset.group===input.dataset.group){if(other.disabled&&other.checked){input.checked=false;notify('This army requires the other equipment option.');return}other.checked=false;}}}const p=data.profiles.find(p=>p.id===card.dataset.profile);card.querySelector('[data-price]').textContent=M.configuration(p,current,selectedOptions(card)).points;card.querySelector('.stat-block').outerHTML=stats(p,selectedOptions(card));card.querySelector('.equip-rules').outerHTML=equipBlock(p,selectedOptions(card));});
let dialogAction=null;
function openWarbandDialog(title,html,action){$('#warband-dialog-title').textContent=title;$('#warband-dialog-body').innerHTML=html;$('#warband-dialog-error').textContent='';dialogAction=action;$('#warband-dialog').showModal();}
$('#warband-dialog-cancel').addEventListener('click',()=>$('#warband-dialog').close());
$('#warband-dialog-confirm').addEventListener('click',()=>{try{dialogAction();save();renderRoster();$('#warband-dialog').close();}catch(e){$('#warband-dialog-error').textContent=e.message;}});
$('#roster-entries').addEventListener('click',e=>{const del=e.target.closest('[data-delete-warband]');if(del){const id=del.dataset.deleteWarband,w=roster.warbands.find(w=>w.id===id),others=wbOptions(id);openWarbandDialog('Remove '+heroName(w)+'?',`<p>${M.warriorCount(w,data)} warriors in this warband.</p><label for="delete-mode">What happens to its warriors?</label><select id="delete-mode"><option value="delete">Delete this whole warband</option>${others?'<option value="move">Move warriors, then remove hero</option>':''}</select>${others?'<label for="delete-target">Move destination</label><select id="delete-target">'+others+'</select>':''}`,()=>M.removeWarband(roster,id,$('#delete-mode').value==='move'?$('#delete-target').value:null,data));return;}
const row=e.target.closest('[data-source]');if(!row)return;const source=row.dataset.source,key=row.dataset.key,list=source==='unassigned'?roster.unassigned:roster.warbands.find(w=>w.id===source).entries,entry=list.find(v=>v.key===key);if(e.target.closest('[data-move]')){openWarbandDialog('Move warriors',`<label for="move-target">Destination warband</label><select id="move-target">${wbOptions(source)}</select><label for="move-quantity">Quantity (up to ${entry.quantity})</label><input id="move-quantity" type="number" min="1" max="${entry.quantity}" value="${entry.quantity}">`,()=>M.move(roster,source,key,$('#move-target').value,Number($('#move-quantity').value),data));return;}
const step=e.target.closest('[data-step]');if(step){const p=data.profiles.find(p=>p.id===entry.profile);if(Number(step.dataset.step)>0&&p.unique)return;entry.quantity+=Number(step.dataset.step);if(entry.quantity===0)list.splice(list.indexOf(entry),1);}else if(e.target.closest('[data-remove]'))list.splice(list.indexOf(entry),1);else return;save();renderRoster();});
$('#points-limit').addEventListener('change',e=>{const value=Number(e.target.value);if(Number.isInteger(value)&&value>0&&value<=100000){roster.limit=value;save();if(data)renderRoster()}else e.target.value=roster.limit;});$('#clear-roster').addEventListener('click',()=>$('#clear-dialog').showModal());$('#cancel-clear').addEventListener('click',()=>$('#clear-dialog').close());$('#confirm-clear').addEventListener('click',()=>{roster.warbands=[];roster.unassigned=[];roster.active=null;roster.army=null;save();renderRoster();$('#clear-dialog').close();});$('#menu').addEventListener('click',()=>{$('#menu').setAttribute('aria-expanded',String($('#sidebar').classList.toggle('open')))});window.addEventListener('hashchange',()=>data&&route());document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});init();
// Printable roster: one card per selection, grouped by warband, then the special rules they use.
function printPrefs(){try{return JSON.parse(localStorage.getItem('army-book-print')||'{}')}catch{return {}}}
function savePrintPrefs(){try{localStorage.setItem('army-book-print',JSON.stringify({photos:$('#print-photos').checked,rules:$('#print-rules').checked}))}catch{}}
function printStats(e){const cell=(k,v,d)=>`<td${d?' class="changed"':''}><b>${statLabels[k]}</b>${esc(v)}${['shoot','courage','intelligence'].includes(k)?'+':k==='movement'?'″':''}</td>`;const row=st=>Object.keys(statLabels).filter(k=>st[k]!==undefined).map(k=>cell(k,st[k],e.changed[k]&&st===e.stats)).join('');return `<table class="print-stats"><tr>${row(e.stats)}</tr>${e.mount?`<tr class="mount"><th colspan="12">${esc(e.mount.name)}</th></tr><tr>${row(e.mount.stats)}</tr>`:''}</table>`;}
function printCard(entry,a,label,photos){const p=data.profiles.find(p=>p.id===entry.profile),c=M.configuration(p,a,entry.options),e=M.effectiveStats(p,a,entry.options,data),tier=M.membership(p,a)?.tier||p.role;
return `<article class="print-card"><div class="print-card-head">${photos&&p.portrait?`<img src="${esc(p.portrait)}" alt="">`:''}<div><small>${esc(label)} · ${esc(tier)}</small><h3>${entry.quantity>1?entry.quantity+'× ':''}${esc(p.name)}</h3></div><span class="pts">${c.points*entry.quantity}<small>pts</small></span></div>${printStats(e)}<dl>${p.wargear.length?`<dt>Wargear</dt><dd>${esc(p.wargear.join(', '))}</dd>`:''}${c.options.length?`<dt>Options</dt><dd>${esc(c.options.map(o=>o.name).join(', '))}</dd>`:''}${p.actions.length?`<dt>Heroic actions</dt><dd>${esc(p.actions.join(', '))}</dd>`:''}${p.rules.length?`<dt>Special rules</dt><dd>${esc(p.rules.join(', '))}</dd>`:''}${p.base.length?`<dt>Base</dt><dd>${esc(p.base.join(' / '))}</dd>`:''}</dl></article>`;}
function renderPrint(){const a=rosterArmy(),photos=$('#print-photos').checked,withRules=$('#print-rules').checked;if(!a){$('#print-sheet').innerHTML='<p class="print-empty">Your roster is empty.</p>';return;}
const total=M.total(roster,data.profiles,data.armies),used=new Map(),equip=new Map();const note=(entry)=>{const p=data.profiles.find(p=>p.id===entry.profile);for(const r of M.equipmentRules(p,a,entry.options,data)){if(!equip.has(r.name))equip.set(r.name,{text:r.text,who:new Set()});equip.get(r.name).who.add(p.name);}for(const r of [...p.rules,...p.actions])if(data.rules?.[r]){if(!used.has(r))used.set(r,new Set());used.get(r).add(p.name);}};
const groups=roster.warbands.map((w,i)=>{const label='Warband '+(i+1);[w.hero,...w.entries].forEach(note);const pts=[w.hero,...w.entries].reduce((s,e)=>s+M.configuration(data.profiles.find(p=>p.id===e.profile),a,e.options).points*e.quantity,0);return `<section class="print-warband"><h2>${label} · ${esc(heroName(w))}<span>${M.warriorCount(w,data)} warriors · ${pts} pts</span></h2><div class="print-cards">${[w.hero,...w.entries].map(e=>printCard(e,a,label,photos)).join('')}</div></section>`;}).join('');
const tag=who=>`<div class="who">${[...who].map(n=>`<span>${esc(n)}</span>`).join('')}</div>`;const equipment=withRules&&equip.size?`<section class="print-rules"><h2>Equipment</h2><table>${[...equip].sort((x,y)=>x[0].localeCompare(y[0])).map(([n,e])=>`<tr><td><b>${esc(n)}:</b> ${esc(e.text)}${tag(e.who)}</td></tr>`).join('')}</table></section>`:'';const rules=withRules&&used.size?`<section class="print-rules"><h2>Special rules</h2><table>${[...used].sort((x,y)=>x[0].localeCompare(y[0])).map(([r,who])=>`<tr><td><b>${esc(r)}:</b> ${esc(data.rules[r].replace(/\*\*/g,''))}<div class="who">${[...who].map(n=>`<span>${esc(n)}</span>`).join('')}</div></td></tr>`).join('')}</table></section>`:'';
const armyRules=withRules&&((a.additionalRules||[]).length||(a.armyRules||[]).length)?`<section class="print-rules print-army-rules"><h2>Army rules — ${esc(a.name)}</h2>${armyRulesHTML(a)}</section>`:'';$('#print-sheet').innerHTML=`<div class="print-head"><div><h1>${esc(a.name)}</h1><p>${roster.warbands.length} warbands · ${M.allEntries(roster).reduce((s,e)=>s+e.quantity,0)} models</p></div><strong>${total}<small> / ${roster.limit} pts</small></strong></div>${groups}${armyRules}${equipment}${rules}<p class="print-foot">MESBG Army Book — fan-made, non-commercial. Miniature images and rules © Games Workshop.</p>`;}
function openPrint(){const prefs=printPrefs();if('photos' in prefs)$('#print-photos').checked=prefs.photos;if('rules' in prefs)$('#print-rules').checked=prefs.rules;renderPrint();$('#print-view').hidden=false;document.body.classList.add('printing');window.scrollTo(0,0);}
function closePrint(){$('#print-view').hidden=true;document.body.classList.remove('printing');}
$('#print-roster').addEventListener('click',openPrint);$('#print-close').addEventListener('click',closePrint);$('#print-now').addEventListener('click',()=>window.print());
$('#print-photos').addEventListener('change',()=>{savePrintPrefs();renderPrint()});$('#print-rules').addEventListener('change',()=>{savePrintPrefs();renderPrint()});
window.addEventListener('beforeprint',()=>{if(data&&M.allEntries(roster).length&&!document.body.classList.contains('printing')){renderPrint();document.body.classList.add('printing','printing-auto');}});
window.addEventListener('afterprint',()=>{if(document.body.classList.contains('printing-auto'))document.body.classList.remove('printing','printing-auto');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#print-view').hidden)closePrint()});
// Mobile search: keep the sidebar inside the visible area above the keyboard, and give the results the room.
const mobile=()=>window.matchMedia('(max-width:800px)').matches;
function fitViewport(){const v=window.visualViewport;if(!v)return;document.documentElement.style.setProperty('--vvh',v.height+'px');document.documentElement.style.setProperty('--vvtop',v.offsetTop+'px');}
if(window.visualViewport){visualViewport.addEventListener('resize',fitViewport);visualViewport.addEventListener('scroll',fitViewport);fitViewport();}
$('#army-search').addEventListener('focus',()=>{if(mobile()){fitViewport();$('#sidebar').classList.add('searching');}});
$('#army-search').addEventListener('blur',()=>setTimeout(()=>{if(document.activeElement!==$('#army-search'))$('#sidebar').classList.remove('searching');},200));
$('#army-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
$('#search-done').addEventListener('click',()=>{$('#army-search').blur();$('#sidebar').classList.remove('searching');});
$('#army-nav').addEventListener('click',e=>{if(e.target.closest('a'))$('#sidebar').classList.remove('searching');});
// One floating tooltip for rule names: hover or keyboard focus on desktop, tap on touch screens.
const tip=document.createElement('div');tip.id='rule-tip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);let tipFor=null;
function showTip(el){const n=el.dataset.rule,txt=ruleText(n).replace(/\*\*/g,'');if(!txt)return;tip.innerHTML=`<strong>${esc(n)}</strong><span>${esc(txt)}</span>`;tip.hidden=false;tipFor=el;el.setAttribute('aria-describedby','rule-tip');
const r=el.getBoundingClientRect(),w=Math.min(360,window.innerWidth-24);tip.style.width=w+'px';const left=Math.max(12,Math.min(r.left+r.width/2-w/2,window.innerWidth-w-12));tip.style.left=left+'px';const h=tip.offsetHeight;const below=r.bottom+8+h<window.innerHeight||r.top<h+16;tip.style.top=(below?r.bottom+8:r.top-h-8)+window.scrollY+'px';tip.classList.toggle('above',!below);}
function hideTip(){if(tipFor)tipFor.removeAttribute('aria-describedby');tip.hidden=true;tipFor=null;}
const hoverable=window.matchMedia('(hover:hover)');
document.addEventListener('mouseover',e=>{const el=e.target.closest('.rule-term[data-rule]');if(el&&hoverable.matches)showTip(el);});
document.addEventListener('mouseout',e=>{const el=e.target.closest('.rule-term[data-rule]');if(el&&hoverable.matches&&!el.contains(e.relatedTarget))hideTip();});
document.addEventListener('focusin',e=>{const el=e.target.closest('.rule-term[data-rule]');if(el&&el.matches(':focus-visible'))showTip(el);});
document.addEventListener('focusout',e=>{if(e.target.closest('.rule-term[data-rule]'))hideTip();});
document.addEventListener('click',e=>{const el=e.target.closest('.rule-term[data-rule]');if(el){e.preventDefault();if(tipFor===el&&!hoverable.matches)hideTip();else showTip(el);return;}if(!e.target.closest('#rule-tip'))hideTip();});
window.addEventListener('scroll',()=>{if(tipFor&&!hoverable.matches)hideTip();},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tipFor)hideTip();});
